import sys
import xml.etree.ElementTree as ET
import sqlite3
from datetime import datetime
import logging
from io import StringIO

def parse_xml_config(xml_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        config = {}
        for elem in root:
            if elem.tag == 'database':
                config['database'] = elem.attrib['file']
            elif elem.tag == 'log':
                config['log_file'] = elem.attrib['file']
            elif elem.tag == 'filter':
                config.setdefault('filters', []).append({
                    'column': elem.attrib['column'],
                    'op': elem.attrib['op'],
                    'value': elem.attrib['value']
                })
        return config
    except Exception as e:
        raise Exception(f"XML parsing error: {str(e)}")

def apply_filters(db_conn, filters):
    cursor = db_conn.cursor()
    try:
        query_parts = ["SELECT * FROM people"]
        params = []
        for i, filter_ in enumerate(filters):
            col = filter_['column']
            op = filter_['op']
            val = filter_['value']
            query_parts.append(f"{col} {op} ?")
            params.append(val)
        query = " AND ".join(query_parts)
        cursor.execute(query, params)
        return cursor.fetchall()
    except Exception as e:
        raise Exception(f"Filter application error: {str(e)}")

def log_event(message):
    timestamp = datetime.utcnow().isoformat() + "Z"
    logging.basicConfig(
        filename=config['log_file'],
        level=logging.INFO,
        format=f"{timestamp} {message}\n"
    )
    logging.info(message)

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    try:
        config = parse_xml_config(sys.argv[1])
        log_event("program start")

        db_path = config['database']
        log_event(f"database file {db_path}")

        log_event("filter age > 30")
        log_event("filter city = Oslo")

        conn = sqlite3.connect(db_path)
        conn.row_factory = sqlite3.Row
        rows = apply_filters(conn, config.get('filters', []))

        if not rows:
            log_event("rows written 0")
            sys.exit(0)

        output = StringIO()
        cursor = conn.cursor()
        cursor.execute("PRAGMA table_info(people)")
        columns = [col[1] for col in cursor.fetchall()]
        output.write("|".join(columns) + "\n")

        for row in rows:
            output.write("|".join(str(row[col]) for col in columns) + "\n")

        log_event(f"rows written {len(rows)}")
        print(output.getvalue())
    except Exception as e:
        log_event(f"ERROR {str(e)}")
        sys.exit(1)
    finally:
        if 'conn' in locals():
            conn.close()

if __name__ == "__main__":
    config = {}
    main()
